  const blocks = [];
  let inside = false;
  let buf = [];
  for (const line of plan) {
    if (!inside && line === fence) { inside = true; buf = []; continue; }
    if (inside && line === '```' && fence === '````markdown') { inside = false; blocks.push(buf.join('\n')); continue; }
    if (inside && line === '```' && fence === '```markdown') { inside = false; blocks.push(buf.join('\n')); continue; }
    if (inside) buf.push(line);
  }
