import re
from pathlib import Path
files = ['spec.md','plan.md','tasks.md','acceptance-criteria.md','goal.md','implementation-summary.md']
pat = re.compile(r'\[[A-Za-z][^\]\[]{2,}\]')
for name in files:
    lines = Path(name).read_text().split('\n')
    fence = None
    inside_hits = 0
    outside_hits = []
    for i, line in enumerate(lines, 1):
        m = re.match(r'^(`{3,})', line)
        if m:
            ticks = m.group(1)
            if fence is None:
                fence = ticks
            elif ticks == fence:
                fence = None
            continue
        if pat.search(line):
            if fence is not None:
                inside_hits += 1
            else:
                outside_hits.append(i)
    print(f"{name}: inside_fence={inside_hits} outside={outside_hits}")
